import { lstatSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'
import { OLD_SCOPE, REPO_ROOT, trackedFiles } from './workspace-manifests'

// Acceptance test for P0-04 AC-1: no tracked file outside archive/ contains the old package scope. The lockfile
// is regenerated by `pnpm install` from the manifests (AC-3 runs it frozen), so it is not scanned here.

const EXEMPT = (file: string): boolean => file.startsWith('archive/') || file === 'pnpm-lock.yaml'

describe('AC-1: no tracked file outside archive/ names the old scope', () => {
  const tracked = trackedFiles()
  const candidates = tracked.filter((f) => !EXEMPT(f))
  const needle = Buffer.from(OLD_SCOPE, 'utf8')

  const offenders: string[] = []
  const scanned: string[] = []
  const notRegularFiles: string[] = []
  for (const file of candidates) {
    const full = join(REPO_ROOT, file)
    let stat
    try {
      stat = lstatSync(full)
    } catch {
      // Tracked but deleted in the working tree: nothing on disk to ship.
      notRegularFiles.push(file)
      continue
    }
    if (!stat.isFile()) {
      // Symlinks (./migrations) and gitlinks: their targets are scanned as their own tracked paths.
      notRegularFiles.push(file)
      continue
    }
    scanned.push(file)
    const bytes = readFileSync(full)
    if (bytes.indexOf(needle) === -1) continue
    bytes
      .toString('utf8')
      .split('\n')
      .forEach((line, i) => {
        if (line.includes(OLD_SCOPE))
          offenders.push(`${file}:${i + 1}: ${line.trim().slice(0, 160)}`)
      })
  }

  it('AC-1: no tracked file outside archive/ contains the old scope', () => {
    // The scan covers every tracked regular file but the exemptions (a guard on the scan itself).
    expect.soft(scanned.length).toBe(candidates.length - notRegularFiles.length)
    expect.soft(scanned.length).toBeGreaterThan(0)
    const files = new Set(offenders.map((o) => o.slice(0, o.indexOf(':'))))
    expect(
      offenders,
      `${offenders.length} occurrences in ${files.size} tracked files:\n${offenders.join('\n')}`,
    ).toEqual([])
  })
})
